 * @utility
 * @version 2.1.11
 */
InferenceBackend* SecondaryModelLoader::get(const std::string& role) const {
    std::lock_guard<std::mutex> lock(slots_mutex_);
    auto it = slots_.find(role);
    return (it == slots_.end()) ? nullptr : it->second.get();

