// Forward declarations for Phase 1+ subsystems.
// Headers included as each phase wires them.
namespace entropic {
class ModelOrchestrator;
class ServerManager;
class ToolExecutor;
class IdentityManager;
class MCPAuthorizationManager;
class AgentEngine;
class SqliteStorageBackend;
